        internal static (long Year, long Month, long Day) FromOrdinal(long n)
        {
            n -= 1;
            long n400 = FloorDiv(n, DI400Y); n = FloorMod(n, DI400Y);
            long year = n400 * 400 + 1;
            long n100 = n / DI100Y; n %= DI100Y;
            long n4 = n / DI4Y; n %= DI4Y;
            long n1 = n / 365; n %= 365;
            year += n100 * 100 + n4 * 4 + n1;
            if (n1 == 4 || n100 == 4) return (year - 1, 12, 31);
            bool leap = n1 == 3 && (n4 != 24 || n100 == 3);
            long month = (n + 50) >> 5;
            long preceding = DaysBefore[month] + (month > 2 && leap ? 1 : 0);
            if (preceding > n) { month -= 1; preceding -= DaysIn[month] + (month == 2 && leap ? 1 : 0); }
            return (year, month, n - preceding + 1);
        }

        /// <summary>The ordinal of the Monday that starts ISO week 1 of the year.</summary>
        internal static long IsoWeek1Monday(long year)
