            return (year, week + 1, day + 1);
        }

        internal static (long, long, long) IsoToGregorian(long year, long week, long day)
        {
            if (year < 1 || year > 9999) throw new ArgumentException($"Year is out of range: {year}");
            if (week <= 0 || week >= 53)
            {
                bool outOfRange = true;
                if (week == 53)
                {
                    long firstWeekday = ToOrdinal(year, 1, 1) % 7;
                    if (firstWeekday == 4 || firstWeekday == 3 && IsLeap(year)) outOfRange = false;
                }
                if (outOfRange) throw new ArgumentException($"Invalid week: {week}");
            }
            if (day <= 0 || day >= 8) throw new ArgumentException($"Invalid weekday: {day} (range is [1, 7])");
