        }

        internal static void CheckDate(long y, long m, long d)
        {
            if (y < 1 || y > 9999) throw new ArgumentException($"year must be in 1..9999, not {y}");
            if (m < 1 || m > 12) throw new ArgumentException($"month must be in 1..12, not {m}");
            long dim = DaysInMonth(y, m);
            if (d < 1 || d > dim) throw new ArgumentException($"day {d} must be in range 1..{dim} for month {m} in year {y}");
        }

        internal static void CheckTime(long h, long mi, long s, long us, long fold)
