            if (mi < 0 || mi > 59) throw new ArgumentException($"minute must be in 0..59, not {mi}");
            if (s < 0 || s > 59) throw new ArgumentException($"second must be in 0..59, not {s}");
            if (us < 0 || us > 999999) throw new ArgumentException($"microsecond must be in 0..999999, not {us}");
            if (fold != 0 && fold != 1) throw new ArgumentException("fold must be either 0 or 1");
        }

