        /// <summary>a / b rounded to the nearest integer, ties to even (CPython's divide_nearest).</summary>
        internal static BigInteger DivideNearest(BigInteger a, BigInteger b)
        {
            if (b.IsZero) throw new DivideByZeroException("division by zero");
            var q = BigInteger.DivRem(a, b, out var r);
