        /// <summary>Python's int / int: the correctly rounded float quotient.</summary>
        internal static double TrueDivide(Int128 a, Int128 b)
        {
            if (b == 0) throw new DivideByZeroException("division by zero");
            const long Exact = 1L << 53;
            if (a > -Exact && a < Exact && b > -Exact && b < Exact) return (double)(long)a / (long)b;
