        /// <summary>float.as_integer_ratio().</summary>
        internal static (BigInteger Num, BigInteger Den) IntegerRatio(double x)
        {
            if (double.IsNaN(x)) throw new ArgumentException("cannot convert NaN to integer ratio");
            if (double.IsInfinity(x)) throw new OverflowException("cannot convert Infinity to integer ratio");
