                    case 'A': text = DayName[wd]; break;
                    case 'b': case 'h': text = MonthAbbr[mo]; break;
                    case 'B': text = MonthName[mo]; break;
                    case 'p': text = H < 12 ? "AM" : "PM"; break;
                    case 'P': text = H < 12 ? "am" : "pm"; break;
                    case 'w': N(wdSun, 1); break;
                    case 'u': N(wd + 1, 1); break;
                    case 'd': N(d, 2); break;
                    case 'e': N(d, 2, ' '); break;
                    case 'm': N(mo, 2); break;
                    case 'y': N(y % 100, 2); break;
                    case 'Y': N(y, 4); break;
                    case 'C': N(y / 100, 2); break;
                    case 'G': N(IsoCalendar(y, mo, d).Year, 4); break;
                    case 'g': N(IsoCalendar(y, mo, d).Year % 100, 2); break;
                    case 'V': N(IsoCalendar(y, mo, d).Week, 2); break;
                    case 'H': N(H, 2); break;
                    case 'k': N(H, 2, ' '); break;
                    case 'I': N(h12, 2); break;
                    case 'l': N(h12, 2, ' '); break;
                    case 'M': N(Mi, 2); break;
                    case 'S': N(S, 2); break;
                    case 'j': N(yday + 1, 3); break;
