                    case 'f': text = us.ToString("000000", Inv); break;
                    case 'z': text = FormatOffset(off, ""); break;
                    case ':' when i + 1 < fmt.Length && fmt[i + 1] == 'z': i++; text = FormatOffset(off, ":"); break;
