                    case 'X': case 'T': text = $"{Pad2(H)}:{Pad2(Mi)}:{Pad2(S)}"; break;
                    case 'F': text = $"{Pad(y, 4)}-{Pad2(mo)}-{Pad2(d)}"; break;
                    case 'R': text = $"{Pad2(H)}:{Pad2(Mi)}"; break;
                    case 'r': text = $"{Pad2(h12)}:{Pad2(Mi)}:{Pad2(S)} {(H < 12 ? "AM" : "PM")}"; break;
                    case 'n': text = "\n"; break;
                    case 't': text = "\t"; break;
                    case '%': text = "%"; break;
