                    if (width > text!.Length) sb.Append(flags.Contains('0') ? '0' : ' ', width - text.Length);
                    sb.Append(text);
                }
            }
            return sb.ToString();
        }

        // ── the local time zone (naive datetimes are local time for timestamps) ──

        static readonly DateTime Epoch = new DateTime(1970, 1, 1, 0, 0, 0, DateTimeKind.Utc);

        /// <summary>Seconds since the epoch of a local wall-clock time (mktime).</summary>
        internal static long LocalEpochSeconds(long y, long mo, long d, long H, long Mi, long S)
        {
            var local = new DateTime((int)y, (int)mo, (int)d, (int)H, (int)Mi, (int)S, DateTimeKind.Unspecified);
            var offset = TimeZoneInfo.Local.GetUtcOffset(local);
            long wall = (ToOrdinal(y, mo, d) - ToOrdinal(1970, 1, 1)) * 86400 + H * 3600 + Mi * 60 + S;
            return wall - (long)offset.TotalSeconds;
        }

        /// <summary>The local wall-clock time and its UTC offset (seconds) at a moment given in seconds since the epoch.</summary>
        internal static (DateTime Local, long Offset, string Name) LocalTime(long seconds)
        {
            var (y, m, d, _, _, _) = UtcFields(seconds);
            CheckDate(y, m, d);
            DateTime utc;
            try { utc = Epoch.AddSeconds(seconds); }
            catch (ArgumentOutOfRangeException) { throw new OverflowException("timestamp out of range for platform time_t"); }
            var zone = TimeZoneInfo.Local;
            var offset = zone.GetUtcOffset(utc);
            var local = DateTime.SpecifyKind(utc + offset, DateTimeKind.Unspecified);
            string name = zone.IsDaylightSavingTime(utc) ? zone.DaylightName : zone.StandardName;
            return (local, (long)offset.TotalSeconds, name);
        }

        /// <summary>A timestamp split into whole seconds and microseconds, rounded half to even like CPython.</summary>
        internal static (long Seconds, long Us) SplitTimestamp(double t)
        {
            if (double.IsNaN(t)) throw new ArgumentException("Invalid value NaN (not a number)");
            if (double.IsInfinity(t) || Math.Abs(t) >= 9.2e18) throw new OverflowException("timestamp out of range for platform time_t");
            double whole = Math.Truncate(t);
            long us = (long)Math.Round((t - whole) * 1e6, MidpointRounding.ToEven);
            long secs = (long)whole;
            if (us >= 1000000) { secs += 1; us -= 1000000; }
            else if (us < 0) { secs -= 1; us += 1000000; }
            return (secs, us);
        }

        internal static (long, long, long, long, long, long) UtcFields(long seconds)
        {
            long days = FloorDiv(seconds, 86400), rem = FloorMod(seconds, 86400);
            var (y, m, d) = FromOrdinal(days + ToOrdinal(1970, 1, 1));
            return (y, m, d, rem / 3600, rem / 60 % 60, rem % 60);
        }

        // ── ISO 8601 parsing (fromisoformat) ──

        static bool IsDigit(char c) => c >= '0' && c <= '9';
        static long Digits(string s, int pos, int n)
        {
            if (pos + n > s.Length) throw new FormatException();
            long v = 0;
            for (int i = pos; i < pos + n; i++) { if (!IsDigit(s[i])) throw new FormatException(); v = v * 10 + (s[i] - '0'); }
            return v;
        }

        /// <summary>Where the date part of an ISO datetime string ends (CPython's _find_isoformat_datetime_separator).</summary>
        internal static int IsoDateEnd(string s)
        {
            int n = s.Length;
            if (n == 7) return 7;
            if (s[4] == '-')
            {
                if (s[5] == 'W')
                {
                    if (n < 8) throw new FormatException();
                    if (n > 8 && s[8] == '-')
                    {
                        if (n == 9) throw new FormatException();
                        if (n > 10 && IsDigit(s[10])) return 8;
                        return 10;
                    }
                    return 8;
                }
                return 10;
            }
            if (s[4] == 'W')
            {
                int idx = 7;
                while (idx < n && IsDigit(s[idx])) idx++;
                if (idx < 9) return idx;
                return idx % 2 == 0 ? 7 : 8;
            }
            return 8;
        }

        /// <summary>YYYY-MM-DD, YYYYMMDD, YYYY-Www[-D], YYYYWww[D] → year, month, day (not yet range-checked).</summary>
        internal static (long, long, long) ParseIsoDate(string s)
        {
            if (s.Length != 7 && s.Length != 8 && s.Length != 10) throw new FormatException();
            long year = Digits(s, 0, 4);
            bool sep = s[4] == '-';
            int pos = 4 + (sep ? 1 : 0);
            if (pos < s.Length && s[pos] == 'W')
            {
                pos++;
                long week = Digits(s, pos, 2);
                pos += 2;
                long day = 1;
                if (s.Length > pos)
                {
                    if ((s[pos] == '-') != sep) throw new FormatException();
                    pos += sep ? 1 : 0;
                    day = Digits(s, pos, 1);
                    pos++;
                }
                if (pos != s.Length) throw new FormatException();
                try { return IsoToGregorian(year, week, day); }
                catch (ArgumentException) { throw new FormatException(); }
            }
            long month = Digits(s, pos, 2);
            pos += 2;
            if (pos >= s.Length || (s[pos] == '-') != sep) throw new FormatException();
            pos += sep ? 1 : 0;
            long dd = Digits(s, pos, 2);
            if (pos + 2 != s.Length) throw new FormatException();
            return (year, month, dd);
        }

        /// <summary>HH[:?MM[:?SS[{.,}fff[fff]]]] → hour, minute, second, microsecond.</summary>
        static long[] ParseHhMmSsFf(string s)
        {
            var comps = new long[4];
            int pos = 0, n = s.Length;
            bool hasSep = false;
            for (int comp = 0; comp < 3; comp++)
            {
                if (n - pos < 2) throw new FormatException();
                comps[comp] = Digits(s, pos, 2);
                pos += 2;
                char next = pos < n ? s[pos] : '\0';
                if (comp == 0) hasSep = next == ':';
                if (pos >= n || comp >= 2) break;
                if (hasSep && next != ':') throw new FormatException();
                pos += hasSep ? 1 : 0;
            }
            if (pos < n)
            {
                if (s[pos] != '.' && s[pos] != ',') throw new FormatException();
                pos++;
                int len = n - pos;
                if (len == 0) throw new FormatException();
                for (int i = pos; i < n; i++) if (!IsDigit(s[i])) throw new FormatException();
                int take = Math.Min(len, 6);
                long frac = Digits(s, pos, take);
                for (int i = take; i < 6; i++) frac *= 10;
                comps[3] = frac;
            }
            return comps;
        }

