            tzinfo? tz = null;
            if (tzPos == s.Length && s[s.Length - 1] == 'Z') tz = timezone.utc;
            else if (tzPos > 0)
            {
                string tzstr = s.Substring(tzPos);
                if (tzstr.Length == 0 || tzstr.Length == 1 || tzstr.Length == 3 || s[tzPos - 1] == 'Z') throw new FormatException();
                var t = ParseHhMmSsFf(tzstr);
                if (t[0] == 0 && t[1] == 0 && t[2] == 0 && t[3] == 0) tz = timezone.utc;
                else
                {
                    CheckTime(t[0], t[1], t[2], t[3], 0);
                    var off = new timedelta(0L, t[0] * 3600 + t[1] * 60 + t[2], t[3]);
                    tz = new timezone(s[tzPos - 1] == '-' ? -off : off);
                }
            }
            return (c[0], c[1], c[2], c[3], tz, nextDay);
        }

        internal static ArgumentException InvalidIso(string s) => new ArgumentException($"Invalid isoformat string: {Builtins.repr(s)}");

        // ── strptime (_strptime.py, C locale) ──

        static readonly Dictionary<string, string> TimeRe = BuildTimeRe();
        static readonly Dictionary<string, Regex> RegexCache = new Dictionary<string, Regex>();

        static string SeqToRe(IEnumerable<string> values, string group)
        {
            var list = new List<string>(values);
            list.Sort((a, b) => b.Length.CompareTo(a.Length));
            var parts = new List<string>();
            foreach (var v in list) if (v != "") parts.Add(Regex.Escape(v));
            return $"(?<{group}>{string.Join("|", parts)})";
        }

        static Dictionary<string, string> BuildTimeRe()
        {
            var m = new Dictionary<string, string>
            {
                ["d"] = @"(?<d>3[0-1]|[1-2]\d|0[1-9]|[1-9]| [1-9])",
                ["f"] = @"(?<f>[0-9]{1,6})",
                ["H"] = @"(?<H>2[0-3]|[0-1]\d|\d| \d)",
                ["k"] = @"(?<H>2[0-3]|[0-1]\d|\d| \d)",
                ["I"] = @"(?<I>1[0-2]|0[1-9]|[1-9]| [1-9])",
                ["l"] = @"(?<I>1[0-2]|0[1-9]|[1-9]| [1-9])",
                ["G"] = @"(?<G>\d\d\d\d)",
                ["j"] = @"(?<j>36[0-6]|3[0-5]\d|[1-2]\d\d|0[1-9]\d|00[1-9]|[1-9]\d|0[1-9]|[1-9])",
                ["m"] = @"(?<m>1[0-2]|0[1-9]|[1-9])",
                ["M"] = @"(?<M>[0-5]\d|\d)",
                ["S"] = @"(?<S>6[0-1]|[0-5]\d|\d)",
                ["U"] = @"(?<U>5[0-3]|[0-4]\d|\d)",
                ["W"] = @"(?<W>5[0-3]|[0-4]\d|\d)",
                ["w"] = @"(?<w>[0-6])",
                ["u"] = @"(?<u>[1-7])",
                ["V"] = @"(?<V>5[0-3]|0[1-9]|[1-4]\d|\d)",
                ["y"] = @"(?<y>\d\d)",
                ["Y"] = @"(?<Y>\d\d\d\d)",
                ["z"] = @"(?<z>[+-]\d\d:?[0-5]\d(:?[0-5]\d(\.\d{1,6})?)?|(?-i:Z))",
                ["A"] = SeqToRe(Lower(DayName), "A"),
                ["a"] = SeqToRe(Lower(DayAbbr), "a"),
                ["B"] = SeqToRe(Lower(MonthName), "B"),
                ["b"] = SeqToRe(Lower(MonthAbbr), "b"),
                ["p"] = SeqToRe(new[] { "am", "pm" }, "p"),
                ["Z"] = SeqToRe(new[] { "utc", "gmt" }, "Z"),
                ["%"] = "%",
            };
            foreach (var c in "dmyCHIMS") m["O" + c] = $@"(?<{c}>\d\d|\d| \d)";
            m["Ow"] = @"(?<w>\d)";
            m["e"] = m["d"]; m["Oe"] = m["Od"]; m["P"] = m["p"]; m["Op"] = m["p"];
            m["T"] = Pattern(m, "%H:%M:%S", "%H:%M:%S");
            m["R"] = Pattern(m, "%H:%M", "%H:%M");
            m["r"] = Pattern(m, "%I:%M:%S %p", "%I:%M:%S %p");
            m["X"] = Pattern(m, "%H:%M:%S", "%H:%M:%S");
            m["x"] = Pattern(m, "%m/%d/%y", "%m/%d/%y");
            m["c"] = Pattern(m, "%a %b %d %H:%M:%S %Y", "%a %b %d %H:%M:%S %Y");
            return m;
        }

        static IEnumerable<string> Lower(string[] xs) { foreach (var x in xs) yield return x.ToLowerInvariant(); }

        /// <summary>The regex of a strptime format (TimeRE.pattern): directives replaced, the rest escaped, whitespace as \s+.</summary>
        static string Pattern(Dictionary<string, string> map, string format, string original)
        {
            var sb = new StringBuilder();
            for (int i = 0; i < format.Length; i++)
            {
                char c = format[i];
                if (char.IsWhiteSpace(c))
                {
                    while (i + 1 < format.Length && char.IsWhiteSpace(format[i + 1])) i++;
                    sb.Append(@"\s+");
                    continue;
                }
                if (c == '\'') { sb.Append("['ʼ]"); continue; }
                if (c != '%') { sb.Append(@"\.^$*+?(){}[]|".IndexOf(c) >= 0 ? "\\" + c : Regex.Escape(c.ToString())); continue; }
                int j = i + 1;
                while (j < format.Length && "-_0^#".IndexOf(format[j]) >= 0) j++;
                while (j < format.Length && format[j] >= '0' && format[j] <= '9') j++;
                string key = "";
                if (j < format.Length && (format[j] == 'O' || format[j] == 'E')) key += format[j++];
                if (j < format.Length && !char.IsWhiteSpace(format[j])) key += format[j++];
                else if (key == "") throw new ArgumentException($"stray % in format '{original}'");
                if (!map.TryGetValue(key, out var re)) throw new ArgumentException($"'{key}' is a bad directive in format '{original}'");
                sb.Append(re);
                i = j - 1;
            }
            return sb.ToString();
        }

        /// <summary>_strptime: the fields a string gives for a format (year, month, day, h, m, s, us, UTC offset).</summary>
        internal static (long Y, long Mo, long D, long H, long Mi, long S, long Us, timezone? Tz) Strptime(string data, string format)
        {
            Regex rx;
            lock (RegexCache)
            {
                if (!RegexCache.TryGetValue(format, out rx!))
                {
                    if (RegexCache.Count > 32) RegexCache.Clear();
                    rx = RegexCache[format] = new Regex(@"\G(?:" + Pattern(TimeRe, format, format) + ")", RegexOptions.IgnoreCase | RegexOptions.CultureInvariant);
                }
            }
            var found = rx.Match(data);
            if (!found.Success) throw new ArgumentException($"time data {Builtins.repr(data)} does not match format {Builtins.repr(format)}");
            if (found.Length != data.Length) throw new ArgumentException($"unconverted data remains: {data.Substring(found.Length)}");

            long? year = null, isoYear = null, isoWeek = null, weekOfYear = null, weekday = null, julian = null;
            long month = 1, day = 1, hour = 0, minute = 0, second = 0, fraction = 0;
            long weekOfYearStart = -1;
            long? gmtoff = null; long gmtoffFraction = 0;
            string? tzname = null;
            string G(string name) => found.Groups[name].Value;
            long Int(string name) => long.Parse(G(name).Trim(), Inv);
            foreach (var name in rx.GetGroupNames())
            {
                if (!found.Groups[name].Success || name.Length == 0 || char.IsDigit(name[0])) continue;
                switch (name)
                {
                    case "y":
                        year = Int("y");
                        if (found.Groups["C"].Success) year += Int("C") * 100;
                        else year += year <= 68 ? 2000 : 1900;
                        break;
                    case "Y": year = Int("Y"); break;
                    case "G": isoYear = Int("G"); break;
                    case "m": month = Int("m"); break;
                    case "B": month = Array.FindIndex(MonthName, x => x.Equals(G("B"), StringComparison.OrdinalIgnoreCase)); break;
                    case "b": month = Array.FindIndex(MonthAbbr, x => x.Length > 0 && x.Equals(G("b"), StringComparison.OrdinalIgnoreCase)); break;
                    case "d": day = Int("d"); break;
                    case "H": hour = Int("H"); break;
                    case "I":
                    {
                        hour = Int("I");
                        string ampm = found.Groups["p"].Success ? G("p").ToLowerInvariant() : "";
                        if (ampm == "" || ampm == "am") { if (hour == 12) hour = 0; }
                        else if (ampm == "pm" && hour != 12) hour += 12;
                        break;
                    }
                    case "M": minute = Int("M"); break;
                    case "S": second = Int("S"); break;
                    case "f": fraction = long.Parse(G("f").PadRight(6, '0'), Inv); break;
                    case "A": weekday = Array.FindIndex(DayName, x => x.Equals(G("A"), StringComparison.OrdinalIgnoreCase)); break;
                    case "a": weekday = Array.FindIndex(DayAbbr, x => x.Equals(G("a"), StringComparison.OrdinalIgnoreCase)); break;
                    case "w": { long w = Int("w"); weekday = w == 0 ? 6 : w - 1; break; }
                    case "u": weekday = Int("u") - 1; break;
                    case "j": julian = Int("j"); break;
                    case "U": weekOfYear = Int("U"); weekOfYearStart = 6; break;
                    case "W": weekOfYear = Int("W"); weekOfYearStart = 0; break;
                    case "V": isoWeek = Int("V"); break;
                    case "z":
                    {
                        string z = G("z");
                        if (z == "Z") { gmtoff = 0; break; }
                        if (z[3] == ':')
                        {
                            z = z.Substring(0, 3) + z.Substring(4);
                            if (z.Length > 5)
                            {
                                if (z[5] != ':') throw new ArgumentException($"Inconsistent use of : in {G("z")}");
                                z = z.Substring(0, 5) + z.Substring(6);
                            }
                        }
                        long hh = long.Parse(z.Substring(1, 2), Inv), mm = long.Parse(z.Substring(3, 2), Inv);
                        long ss = z.Length >= 7 ? long.Parse(z.Substring(5, 2), Inv) : 0;
                        gmtoff = hh * 3600 + mm * 60 + ss;
                        string rest = z.Length > 8 ? z.Substring(8) : "";
                        gmtoffFraction = long.Parse(rest.PadRight(6, '0'), Inv);
                        if (z[0] == '-') { gmtoff = -gmtoff; gmtoffFraction = -gmtoffFraction; }
                        break;
                    }
                    case "Z": tzname = G("Z"); break;
                }
            }

            if (isoYear != null)
            {
                if (julian != null)
                    throw new ArgumentException("Day of the year directive '%j' is not compatible with ISO year directive '%G'. Use '%Y' instead.");
                if (isoWeek == null || weekday == null)
                    throw new ArgumentException("ISO year directive '%G' must be used with the ISO week directive '%V' and a weekday directive ('%A', '%a', '%w', or '%u').");
            }
            else if (isoWeek != null)
            {
                if (year == null || weekday == null)
                    throw new ArgumentException("ISO week directive '%V' must be used with the ISO year directive '%G' and a weekday directive ('%A', '%a', '%w', or '%u').");
                throw new ArgumentException("ISO week directive '%V' is incompatible with the year directive '%Y'. Use the ISO year '%G' instead.");
            }

            bool leapYearFix = false;
            if (year == null)
            {
                if (month == 2 && day == 29) { year = 1904; leapYearFix = true; }
                else year = 1900;
            }
            long yr = year.Value;
            if (julian == null && weekday != null)
            {
                if (weekOfYear != null)
                {
                    bool startsMon = weekOfYearStart == 0;
                    long firstWeekday = (ToOrdinal(yr, 1, 1) + 6) % 7, dow = weekday.Value;
                    if (!startsMon) { firstWeekday = (firstWeekday + 1) % 7; dow = (dow + 1) % 7; }
                    long week0 = (7 - firstWeekday) % 7;
                    julian = weekOfYear == 0 ? 1 + dow - firstWeekday : 1 + week0 + 7 * (weekOfYear.Value - 1) + dow;
                }
                else if (isoYear != null && isoWeek != null)
                {
                    (yr, month, day) = IsoToGregorian(isoYear.Value, isoWeek.Value, weekday.Value + 1);
                }
                if (julian != null && julian <= 0)
                {
                    yr -= 1;
                    julian += IsLeap(yr) ? 366 : 365;
                }
            }
            if (julian == null) CheckDate(yr, month, day);
            else
            {
                CheckDate(yr, 1, 1);
                (yr, month, day) = FromOrdinal(julian.Value - 1 + ToOrdinal(yr, 1, 1));
            }
            if (leapYearFix) yr = 1900;

            timezone? tz = null;
            if (gmtoff != null)
            {
                var delta = new timedelta(0L, gmtoff.Value, gmtoffFraction);
                tz = string.IsNullOrEmpty(tzname) ? new timezone(delta) : new timezone(delta, tzname);
            }
            return (yr, month, day, hour, minute, second, fraction, tz);
        }
    }

    /// <summary>A runtime value with its own truth (Python's __bool__): bool(x), if x, not x.</summary>
    internal interface IPyBool
    {
        bool __bool__();
    }

    // Python's floor division, modulo, abs and sum of timedeltas (the emitter calls these helpers for //, %, abs(), ...)
    internal static partial class Builtins
    {
        public static long floordiv(timedelta a, timedelta b) => a.__floordiv__(b);
        public static timedelta floordiv(timedelta a, long b) => a.__floordiv__(b);
        public static timedelta floordiv(timedelta a, BigInteger b) => a.__floordiv__(b);
        public static timedelta mod(timedelta a, timedelta b) => a % b;
        public static (long, timedelta) divmod(timedelta a, timedelta b) => (a.__floordiv__(b), a % b);
        public static timedelta abs(timedelta x) => x.__abs__();
        public static timedelta sum(IEnumerable<timedelta> xs, timedelta start) { var s = start; foreach (var x in xs) s += x; return s; }
    }
}

namespace Typhon.Stdlib
{
    using System;
    using System.Collections;
    using System.Collections.Generic;
    using System.Globalization;
    using System.Numerics;
    using System.Runtime.CompilerServices;
    using Typhon.Runtime;

    /// <summary>The datetime module: date, time, datetime, timedelta, tzinfo, timezone, MINYEAR, MAXYEAR, UTC.</summary>
    internal static class datetime_
    {
        public const long MINYEAR = 1, MAXYEAR = 9999;
        public static readonly timezone UTC = timezone.utc;

        static readonly CultureInfo Inv = CultureInfo.InvariantCulture;

        /// <summary>A duration: days, seconds (0..86399) and microseconds (0..999999), normalized like CPython.</summary>
        internal sealed class timedelta : IPyRepr, IPyBool, IComparable<timedelta>, IComparable, IEquatable<timedelta>
        {
            readonly long _days, _seconds, _us;

            public long days => _days;
            public long seconds => _seconds;
            public long microseconds => _us;

            public static readonly timedelta min = new timedelta(-999999999L);
            public static readonly timedelta max = new timedelta(999999999L, 86399L, 999999L);
            public static readonly timedelta resolution = new timedelta(0L, 0L, 1L);

            public timedelta() { }

            /// <summary>timedelta(days, seconds, ...) of ints: exact.</summary>
            public timedelta(long days = 0, long seconds = 0, long microseconds = 0, long milliseconds = 0, long minutes = 0, long hours = 0, long weeks = 0)
            {
                Int128 us;
                try
                {
                    us = checked((Int128)microseconds + (Int128)milliseconds * 1000 + (Int128)seconds * DateTimeOps.UsPerSecond +
                                 (Int128)minutes * 60 * DateTimeOps.UsPerSecond + (Int128)hours * 3600 * DateTimeOps.UsPerSecond +
                                 (Int128)days * DateTimeOps.UsPerDay + (Int128)weeks * 7 * DateTimeOps.UsPerDay);
                }
                catch (OverflowException) { throw new OverflowException("Python int too large to convert to C int"); }
                (_days, _seconds, _us) = Split(us);
            }

            /// <summary>timedelta(...) with floats: CPython's accumulation (exact integer parts, fractions rounded half to even).</summary>
            public timedelta(double days = 0, double seconds = 0, double microseconds = 0, double milliseconds = 0, double minutes = 0, double hours = 0, double weeks = 0)
            {
                Int128 x = 0;
                double leftover = 0;
                try
                {
                    Accum(ref x, microseconds, 1, ref leftover);
                    Accum(ref x, milliseconds, 1000, ref leftover);
                    Accum(ref x, seconds, DateTimeOps.UsPerSecond, ref leftover);
                    Accum(ref x, minutes, 60 * DateTimeOps.UsPerSecond, ref leftover);
                    Accum(ref x, hours, 3600 * DateTimeOps.UsPerSecond, ref leftover);
                    Accum(ref x, days, DateTimeOps.UsPerDay, ref leftover);
                    Accum(ref x, weeks, 7 * DateTimeOps.UsPerDay, ref leftover);
                    if (leftover != 0)
                    {
                        double whole = Math.Round(leftover, MidpointRounding.AwayFromZero);
                        if (Math.Abs(whole - leftover) == 0.5)
                        {
                            int odd = (int)(x & 1);
                            whole = 2.0 * Math.Round((leftover + odd) * 0.5, MidpointRounding.AwayFromZero) - odd;
                        }
                        x = checked(x + (Int128)whole);
                    }
                }
                catch (OverflowException e) when (!e.Message.StartsWith("cannot")) { throw new OverflowException("Python int too large to convert to C int"); }
                (_days, _seconds, _us) = Split(x);
            }

            static void Accum(ref Int128 sofar, double num, long factor, ref double leftover)
            {
                if (num == 0) return;
                if (double.IsNaN(num)) throw new ArgumentException("cannot convert float NaN to integer");
                if (double.IsInfinity(num)) throw new OverflowException("cannot convert float infinity to integer");
                double intpart = Math.Truncate(num), frac = num - intpart;
                sofar = checked(sofar + checked((Int128)intpart) * factor);
                if (frac == 0) return;
                double d = factor * frac;
                double ip = Math.Truncate(d);
                sofar = checked(sofar + (Int128)ip);
                leftover += d - ip;
            }

            timedelta(long d, long s, long us, bool normalized) { _days = d; _seconds = s; _us = us; }

            static (long, long, long) Split(Int128 us)
            {
                Int128 secs = DateTimeOps.FloorDiv(us, DateTimeOps.UsPerSecond);
                long rus = (long)(us - secs * DateTimeOps.UsPerSecond);
                Int128 d = DateTimeOps.FloorDiv(secs, 86400);
                long rs = (long)(secs - d * 86400);
                if (d > 999999999 || d < -999999999)
                {
                    if (d > int.MaxValue || d < int.MinValue) throw new OverflowException("Python int too large to convert to C int");
                    throw new OverflowException($"days={d}; must have magnitude <= 999999999");
                }
                return ((long)d, rs, rus);
            }

            internal static timedelta FromMicroseconds(Int128 us) { var (d, s, u) = Split(us); return new timedelta(d, s, u, true); }
            internal static timedelta FromMicroseconds(BigInteger us)
            {
                if (us > (BigInteger)long.MaxValue * 100 || us < (BigInteger)long.MinValue * 100) throw new OverflowException("Python int too large to convert to C int");
                return FromMicroseconds((Int128)us);
            }
            internal Int128 TotalMicroseconds => ((Int128)_days * 86400 + _seconds) * DateTimeOps.UsPerSecond + _us;

            public double total_seconds() => DateTimeOps.TrueDivide(TotalMicroseconds, DateTimeOps.UsPerSecond);

            public static timedelta operator +(timedelta a, timedelta b) => FromMicroseconds(a.TotalMicroseconds + b.TotalMicroseconds);
            public static timedelta operator -(timedelta a, timedelta b) => FromMicroseconds(a.TotalMicroseconds - b.TotalMicroseconds);
            public static timedelta operator -(timedelta a) => FromMicroseconds(-a.TotalMicroseconds);
            public static timedelta operator +(timedelta a) => a;
            public static timedelta operator *(timedelta a, long n) => FromMicroseconds((BigInteger)a.TotalMicroseconds * n);
            public static timedelta operator *(long n, timedelta a) => a * n;
            public static timedelta operator *(timedelta a, BigInteger n) => FromMicroseconds((BigInteger)a.TotalMicroseconds * n); // big-int mode
            public static timedelta operator *(BigInteger n, timedelta a) => a * n;
            public static timedelta operator *(timedelta a, double f)
            {
                var (num, den) = DateTimeOps.IntegerRatio(f);
                return FromMicroseconds(DateTimeOps.DivideNearest((BigInteger)a.TotalMicroseconds * num, den));
            }
            public static timedelta operator *(double f, timedelta a) => a * f;
            public static double operator /(timedelta a, timedelta b) => DateTimeOps.TrueDivide(a.TotalMicroseconds, b.TotalMicroseconds);
            public static timedelta operator /(timedelta a, long n) => FromMicroseconds(DateTimeOps.DivideNearest((BigInteger)a.TotalMicroseconds, n));
            public static timedelta operator /(timedelta a, BigInteger n) => FromMicroseconds(DateTimeOps.DivideNearest((BigInteger)a.TotalMicroseconds, n));
            public static timedelta operator /(timedelta a, double f)
            {
                var (num, den) = DateTimeOps.IntegerRatio(f);
                return FromMicroseconds(DateTimeOps.DivideNearest((BigInteger)a.TotalMicroseconds * den, num));
            }
            public static timedelta operator %(timedelta a, timedelta b)
            {
                var d = b.TotalMicroseconds;
                if (d == 0) throw new DivideByZeroException("division by zero");
                return FromMicroseconds(DateTimeOps.FloorMod(a.TotalMicroseconds, d));
            }
            public long __floordiv__(timedelta b)
            {
                var d = b.TotalMicroseconds;
                if (d == 0) throw new DivideByZeroException("division by zero");
                return checked((long)DateTimeOps.FloorDiv(TotalMicroseconds, d));
            }
            public timedelta __floordiv__(long n)
            {
                if (n == 0) throw new DivideByZeroException("division by zero");
                return FromMicroseconds(DateTimeOps.FloorDiv(TotalMicroseconds, n));
            }
            public timedelta __floordiv__(BigInteger n)
            {
                if (n.IsZero) throw new DivideByZeroException("division by zero");
                var q = BigInteger.DivRem((BigInteger)TotalMicroseconds, n, out var r);
                if (!r.IsZero && (r.Sign < 0) != (n.Sign < 0)) q -= 1;
                return FromMicroseconds(q);
            }
            public timedelta __abs__() => _days < 0 ? -this : this;
            public bool __bool__() => _days != 0 || _seconds != 0 || _us != 0;

            public static bool operator <(timedelta a, timedelta b) => a.CompareTo(b) < 0;
            public static bool operator <=(timedelta a, timedelta b) => a.CompareTo(b) <= 0;
            public static bool operator >(timedelta a, timedelta b) => a.CompareTo(b) > 0;
            public static bool operator >=(timedelta a, timedelta b) => a.CompareTo(b) >= 0;

            public int CompareTo(timedelta? o)
            {
                if (o is null) throw new InvalidCastException("'<' not supported between instances of 'datetime.timedelta' and 'NoneType'");
                int c = _days.CompareTo(o._days);
                if (c == 0) c = _seconds.CompareTo(o._seconds);
                return c != 0 ? c : _us.CompareTo(o._us);
            }
            int IComparable.CompareTo(object? o) => o is timedelta t ? CompareTo(t)
                : throw new InvalidCastException($"'<' not supported between instances of 'datetime.timedelta' and '{DateTimeOps.PyTypeName(o)}'");
            public bool Equals(timedelta? o) => o is not null && _days == o._days && _seconds == o._seconds && _us == o._us;
            public override bool Equals(object? o) => o is timedelta t && Equals(t);
            public override int GetHashCode() => HashCode.Combine(_days, _seconds, _us);

            public override string ToString()
            {
                long mm = _seconds / 60, ss = _seconds % 60, hh = mm / 60;
                mm %= 60;
                string s = hh.ToString(Inv) + ":" + DateTimeOps.Pad2(mm) + ":" + DateTimeOps.Pad2(ss);
                if (_days != 0) s = _days.ToString(Inv) + (Math.Abs(_days) != 1 ? " days, " : " day, ") + s;
                if (_us != 0) s += "." + _us.ToString("000000", Inv);
                return s;
            }

            public string __repr__()
            {
                var args = new List<string>();
                if (_days != 0) args.Add("days=" + _days.ToString(Inv));
                if (_seconds != 0) args.Add("seconds=" + _seconds.ToString(Inv));
                if (_us != 0) args.Add("microseconds=" + _us.ToString(Inv));
                if (args.Count == 0) args.Add("0");
                return "datetime.timedelta(" + string.Join(", ", args) + ")";
            }
        }

        /// <summary>The abstract base of time zones (utcoffset, tzname, dst of a datetime).</summary>
        internal abstract class tzinfo : IPyRepr
        {
            public abstract timedelta? utcoffset(datetime? dt);
            public abstract string? tzname(datetime? dt);
            public virtual timedelta? dst(datetime? dt) => null;
            public virtual datetime fromutc(datetime dt) => throw new NotImplementedException("a tzinfo subclass must implement fromutc()");
            public abstract string __repr__();
        }

        /// <summary>A fixed offset from UTC (timezone.utc, timezone(timedelta(hours=5)), timezone(offset, name)).</summary>
        internal sealed class timezone : tzinfo, IEquatable<timezone>
        {
            readonly timedelta _offset;
            readonly string? _name;

            public static readonly timezone utc = new timezone(new timedelta(), null, true);
